import { cache } from "../infra/cache";
import { db } from "../infra/db";

interface QuoteRequest {
  shipmentId: string;
}

export async function handleQuote(req: QuoteRequest): Promise<number> {
  const cached = await cache.get(`quote:${req.shipmentId}`);
  if (cached !== null) {
    return Number(cached);
  }
  const row = await db.quotes.findOne({ shipmentId: req.shipmentId });
  const live = await fetch(
    `https://rates.example.net/v1/surcharge?shipment=${req.shipmentId}`,
  );
  const surcharge = (await live.json()).surchargeCents;
  return row.priceCents + surcharge;
}
